    private static string StrictBody(string kind)
    {
        var body=JsonSerializer.SerializeToNode(new{expectedRevision=1,parentFolderId=(Guid?)null},ProtectionFixture.Json)!.AsObject();var fields=new[]{"recordId","cascade","actor","vaultAccess","folderId","ownerId","profileIds","collectionIds","name","fields","keyWrappers","envelope","editedAt","trashOperationId","deletedAt","purgeAt"};if(fields.Contains(kind))body[kind]=null;if(kind=="unknown")body["secret"]=null;if(kind is "zero" or "negative" or "unsafe")body["expectedRevision"]=kind=="zero"?0:kind=="negative"?-1:9007199254740992;if(kind=="missingRevision")body.Remove("expectedRevision");if(kind=="missingFolder")body.Remove("parentFolderId");if(kind=="caseRevision"){body.Remove("expectedRevision");body["ExpectedRevision"]=1;}if(kind=="caseFolder"){body.Remove("parentFolderId");body["ParentFolderId"]=null;}if(kind=="numericString")body["expectedRevision"]="1";if(kind=="nullRevision")body["expectedRevision"]=null;if(kind=="fraction")body["expectedRevision"]=1.5;if(kind=="overflow")body["expectedRevision"]=9223372036854775808m;if(kind is "folderZero" or "folderBad" or "folderUppercase" or "folderCompact" or "folderNumeric")body["parentFolderId"]=kind switch{"folderZero"=>Guid.Empty.ToString(),"folderBad"=>"bad","folderUppercase"=>"ABCDEFAB-1234-4321-ABCD-123456789ABC",_=>"abcdefab12344321abcd123456789abc"};if(kind=="folderNumeric")body["parentFolderId"]=1;
        return kind switch{"duplicateRevision"=>"{\"expectedRevision\":1,\"expectedRevision\":1,\"parentFolderId\":null}","duplicateFolder"=>"{\"expectedRevision\":1,\"parentFolderId\":null,\"parentFolderId\":null}","null"=>"null","array"=>"[]","empty"=>"",_=>body.ToJsonString()};
    }

