    private static HttpRequestMessage PutParent(State s,string path,byte[] body){var split=path.IndexOf('?');var uri=split<0?path+"/parent":path[..split]+"/parent"+path[split..];var r=Request(s,body,uri);r.Method=HttpMethod.Put;return r;}
    private async Task<HttpResponseMessage> Move(State s,Guid id,long revision=1,Guid? destination=null){using var req=PutParent(s,"/api/folders/"+id,Bytes(new{expectedRevision=revision,parentFolderId=destination}));return await Gateway.Client.SendAsync(req);}
    private async Task<VaultFolder> FolderRow(Guid id){await using var db=fixture.Context();return await db.Folders.AsNoTracking().SingleAsync(x=>x.PublicId==id);}
    private async Task<VaultRecord> RecordRow(Guid id){await using var db=fixture.Context();return await db.Records.AsNoTracking().SingleAsync(x=>x.PublicId==id);}
    private async Task Moved(VaultFolder original,VaultFolder? destination,MoveFolderOutput output)
    {Fields(output,"folderId","parentFolderId","revision","serverSequence");Assert.Equal(original.PublicId,output.FolderId);Assert.Equal(destination?.PublicId,output.ParentFolderId);Assert.Equal(original.Revision+1,output.Revision);Assert.True(output.ServerSequence>original.ServerSequence);Assert.InRange(output.ServerSequence,1,ProtocolBinary.MaxInteger);var row=await FolderRow(original.PublicId);Assert.Equal(original.AccountId,row.AccountId);Assert.Equal(original.Envelope,row.Envelope);Assert.Equal(original.EditedAt,row.EditedAt);Assert.Equal(destination?.Id,row.ParentFolderId);Assert.Equal(output.Revision,row.Revision);Assert.Equal(output.ServerSequence,row.ServerSequence);Assert.Null(row.DeletedAt);Assert.Null(row.PurgeAt);Assert.NotEqual(original.ConcurrencyStamp,row.ConcurrencyStamp);}
    private async Task<string> Stable(State s,params long[] ignored){var node=JsonNode.Parse(await Snapshot(s))!.AsObject();var rows=node["Folders"]!.AsArray();foreach(var row in rows.ToArray())if(ignored.Contains(row!["Id"]!.GetValue<long>()))rows.Remove(row);return node.ToJsonString();}
